<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class DashboardController extends Controller {
 public function index(Request $r){$u=$r->user();$p=$r->attributes->get('academic_period');$data=['mode'=>'general','period'=>$p];
  if($u->hasRole('student')&&$u->student_id){$data['mode']='student';$data['student']=DB::table('students')->find($u->student_id);$data['today']=$this->lessons($p?->id)->where('l.study_group_id',$data['student']->current_group_id)->get();$data['avg']=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where('gr.student_id',$u->student_id)->when($p,fn($q)=>$q->where('l.academic_period_id',$p->id))->avg(DB::raw('CAST(gr.value AS REAL)'));$data['missed']=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('a.student_id',$u->student_id)->whereIn('a.status',['absent','sick','excused'])->when($p,fn($q)=>$q->where('l.academic_period_id',$p->id))->count();}
  elseif($u->hasRole('teacher')&&$u->teacher_id){$data['mode']='teacher';$data['today']=$this->lessons($p?->id)->where('l.teacher_id',$u->teacher_id)->get();$data['groups']=DB::table('schedule_entries as e')->join('study_groups as g','g.id','=','e.study_group_id')->where('e.teacher_id',$u->teacher_id)->when($p,fn($q)=>$q->where('e.academic_period_id',$p->id))->select('g.id','g.name')->distinct()->orderBy('g.name')->get();}
  elseif($u->hasRole('curator')&&$u->teacher_id){$data['mode']='curator';$data['group']=DB::table('study_groups')->where('curator_teacher_id',$u->teacher_id)->first();if($data['group']){$gid=$data['group']->id;$data['studentCount']=DB::table('students')->where('current_group_id',$gid)->where('status','active')->count();$data['absences']=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('l.study_group_id',$gid)->whereIn('a.status',['absent','sick','excused'])->when($p,fn($q)=>$q->where('l.academic_period_id',$p->id))->count();}}
  else {$data['groups']=DB::table('study_groups')->where('active',1)->count();$data['students']=DB::table('students')->where('status','active')->count();$data['todayCount']=$this->lessons($p?->id)->count();$data['unmarked']=DB::table('lesson_occurrences as l')->whereDate('l.lesson_date',now()->toDateString())->when($p,fn($q)=>$q->where('l.academic_period_id',$p->id))->whereNotExists(fn($q)=>$q->select(DB::raw(1))->from('attendance_records as a')->whereColumn('a.lesson_occurrence_id','l.id'))->count();}
  return view('dashboard',$data);
 }
 private function lessons($period){return DB::table('lesson_occurrences as l')->join('subjects as s','s.id','=','l.subject_id')->join('study_groups as g','g.id','=','l.study_group_id')->leftJoin('rooms as rm','rm.id','=','l.room_id')->whereDate('l.lesson_date',now()->toDateString())->where('l.status','!=','cancelled')->when($period,fn($q)=>$q->where('l.academic_period_id',$period))->select('l.*','s.name as subject_name','g.name as group_name','rm.name as room_name')->orderBy('l.lesson_number');}
}
